python3 << 'PYEOF'
import json

# Load the flow file
with open('/work/output/artifacts/skill-flow-ixp-routing/invoice-extraction/InvoiceExtraction/InvoiceExtraction/InvoiceExtraction.flow', 'r') as f:
    flow = json.load(f)

# Load the IxP definition
with open('/tmp/ixp-node-def.json', 'r') as f:
    ixp_def = json.load(f)

# Add IxP definition to definitions array if not already present
existing_types = [d['nodeType'] for d in flow['definitions']]
if ixp_def['nodeType'] not in existing_types:
    flow['definitions'].append(ixp_def)
    print(f"Added IxP definition: {ixp_def['nodeType']}")
else:
    print("IxP definition already present")

# Add variables for new nodes if not present
existing_var_ids = [v['id'] for v in flow['variables']['nodes']]

new_vars = [
    {
